prompt --application/shared_components/user_interface/lovs/empresa
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(10544615093126509)
,p_lov_name=>'EMPRESA'
,p_static_id=>'empresas-nombre-empresa'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT e.nombre_empresa AS display_value,',
'       e.id_empresa     AS return_value',
'  FROM empresas e',
'  JOIN usuario u ',
'    ON e.id_empresa = u.id_empresa  -- Verifica si en la tabla usuario es ID_EMPRESA o EMPRESA_ID',
' WHERE e.estado = ''ACTIVO''',
'   AND UPPER(u.username) = UPPER(:APP_USER)',
' ORDER BY e.nombre_empresa;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'RETURN_VALUE'
,p_display_column_name=>'DISPLAY_VALUE'
,p_version_scn=>'SH256:zMpo9175HYsPkP74JUtp44Qzz3YoEKVkuQiO_cXX2us'
