 p_id=>wwv_flow_imp.id(11950647600514906)
,p_plug_name=>'Lista de Presupuestos'
,p_static_id=>'grid_presupuestos'
,p_title=>'Lista de Presupuestos'
,p_region_css_classes=>'card-3d u-shadow-10'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    p.ID_PRESUPUESTO,    ',
'    p.ID_PRESUPUESTO AS print_link,',
'    c.razon_social,',
'    c.rif,',
'    p.Folio,',
'    p.tipo_cambio,',
'    p.subtotal,',
'    p.impuesto_iva,',
'    p.total,',
'    p.fecha_emision,',
'    p.fecha_vencimiento,            ',
'    CASE p.estado',
'      WHEN ''APROBADO''  THEN ''background-color: #e6f4ea; color: #137333;''',
'      WHEN ''PENDIENTE'' THEN ''background-color: #fef7e0; color: #b06000;''',
'      WHEN ''CANCELADO'' THEN ''background-color: #fce8e6; color: #c5221f;''',
'      WHEN ''FACTURADO'' THEN ''background-color: #e8f0fe; color: #1a73e8;''',
'      ELSE ''background-color: #f1f3f4; color: #5f6368;''',
'    END AS estado_css,',
'    p.creado_por,',
'    p.fecha_creacion,       ',
'    p.observaciones,',
'    p.estado',
'  FROM presupuestos p, clientes c',
' WHERE p.id_cliente = c.id_cliente',
'   AND p.id_empresa = c.id_empresa',
'   AND c.estado = ''ACTIVO''',
'   AND p.estado NOT IN (''CANCELADO'', ''FACTURADO'', ''ENVIADO'')'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
