wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(12541094704283236)
,p_plug_name=>'Resumen Financiero'
,p_static_id=>'totales'
,p_title=>'Resumen Financiero'
,p_region_css_classes=>'u-textRight'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_region_attributes=>'style="text-align: right; font-weight: bold; font-size: 16px;"'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>50
,p_plug_grid_column_span=>4
,p_plug_display_column=>9
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_id_presupuesto    NUMBER := :P5_ID_PRESUPUESTO;',
'    v_subtotal_bruto    NUMBER := 0;',
'    v_total_descuento   NUMBER := 0;',
'    v_subtotal_neto     NUMBER := 0;',
'    v_iva               NUMBER := 0;',
'    v_total             NUMBER := 0;',
'    v_html              VARCHAR2(4000);',
'BEGIN',
'    -- Si hay un presupuesto seleccionado, calculamos sus valores',
'    IF v_id_presupuesto IS NOT NULL THEN',
'        SELECT NVL(SUM(cantidad * precio_unitario), 0),',
'               NVL(SUM(monto_descuento), 0),',
'               NVL(SUM(subtotal_linea), 0),',
'               NVL(SUM(monto_impuesto), 0)',
'          INTO v_subtotal_bruto, v_total_descuento, v_subtotal_neto, v_iva',
'          FROM presupuestos_det',
'         WHERE id_presupuesto = v_id_presupuesto;',
'    END IF;',
'',
'    v_total := v_subtotal_neto + v_iva;',
'',
'    v_html := ''',
'    <div style="width: 320px; border: 1px solid #d0d0d0; border-radius: 8px; padding: 16px; background-color: #ffffff; box-shadow: 0 2px 6px rgba(0,0,0,0.08); margin-left: auto;">',
'      <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'        <span style="color: #606060; font-size: 13px;">Subtotal Bruto:</span>',
'        <strong style="color: #333333; font-size: 14px;">'' || TO_CHAR(v_subtotal_bruto, ''$999,999,990.00'') || ''</strong>',
'      </div>'';',
'',
'    IF v_total_descuento > 0 THEN',
'        v_html := v_html || ''',
'      <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'        <span style="color: #d9534f; font-size: 13px;">Descuento Total:</span>',
'        <strong style="color: #d9534f; font-size: 14px;">-'' || TO_CHAR(v_total_descuento, ''$999,999,990.00'') || ''</strong>',
'      </div>'';',
'    END IF;',
'',
'    v_html := v_html || ''',
'      <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'        <span style="color: #606060; font-size: 13px;">Subtotal Neto:</span>',
'        <strong style="color: #333333; font-size: 14px;">'' || TO_CHAR(v_subtotal_neto, ''$999,999,990.00'') || ''</strong>',
'      </div>',
'      <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'        <span style="color: #606060; font-size: 13px;">Impuestos / IVA:</span>',
'        <strong style="color: #333333; font-size: 14px;">'' || TO_CHAR(v_iva, ''$999,999,990.00'') || ''</strong>',
'      </div>',
'      <div style="display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; background-color: #40a6d4ff; color: #ffffff; font-weight: bold; font-size: 16px; border-radius: 6px; margin-top: 10px;">',
'        <span>Total:</span>',
'        <span>'' || TO_CHAR(v_total, ''$999,999,990.00'') || ''</span>',
'      </div>',
'    </div>'';',
'',
'    RETURN v_html;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P5_ID_PRESUPUESTO'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Resumen Financiero'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
