,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- 1. Ejecutamos el procedimiento normal',
'pkg_presupuestos.prc_guardar_presupuesto(',
'    p_id_presupuesto    => :P7_ID_PRESUPUESTO,',
'    p_id_empresa        => :P7_ID_EMPRESA,',
'    p_id_cliente        => :P7_ID_CLIENTE,',
'    p_folio             => :P7_FOLIO,',
'    p_cod_moneda        => :P7_COD_MONEDA,',
'    p_fecha_vencimiento => :P7_FECHA_VENCIMIENTO,',
'    p_fecha_emision     => :P7_FECHA_EMISION,',
'    p_tipo_cambio       => :P7_TIPO_CAMBIO,',
'    p_estado            => :P7_ESTADO,',
'    p_observaciones     => :P7_OBSERVACIONES,',
'    p_usuario           => :APP_USER',
');',
'',
unistr('-- 2. Si el ID de la p\00E1gina 7 sigue nulo, lo rescatamos de la base de datos'),
'IF :P7_ID_PRESUPUESTO IS NULL THEN',
'    BEGIN',
'        SELECT MAX(id_presupuesto)',
'        INTO :P7_ID_PRESUPUESTO',
unistr('        FROM presupuestos -- Aseg\00FArate de que este sea el nombre real de tu tabla'),
'        WHERE id_empresa = :P7_ID_EMPRESA',
'          AND folio = :P7_FOLIO;',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            NULL;',
'    END;',
'END IF;',
'',
unistr('-- 4. Mensaje de \00E9xito'),
'apex_application.g_print_success_message := ''Presupuesto Guardado Exitosamente (ID: '' || :P7_ID_PRESUPUESTO || '').'';'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error al guardar el presupuesto: #SQLERRM#'
