wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(29963866505095675)
,p_plug_name=>'Lista de Facturas'
,p_static_id=>'listado-facturas'
,p_title=>'Lista de Facturas'
,p_region_css_classes=>'card-3d u-shadow-10'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT f.id_factura AS detalle_link,',
'       f.id_factura AS print_link,',
'       f.id_factura,',
'       c.razon_social,',
'       f.rfc_receptor AS rif,',
'       f.folio_factura AS folio,',
'       f.subtotal,',
'       f.monto_impuesto AS impuesto_iva,',
'       f.monto_total AS total,',
'       f.fecha_emision,',
'       f.fecha_vencimiento,',
'       CASE f.estado',
'          WHEN ''TIMBRADA''  THEN ''background-color: #e6f4ea; color: #137333;''',
'          WHEN ''PAGADA''    THEN ''background-color: #e8f0fe; color: #1a73e8;''',
'          WHEN ''PENDIENTE'' THEN ''background-color: #fef7e0; color: #b06000;''',
'          WHEN ''CANCELADA'' THEN ''background-color: #fce8e6; color: #c5221f;''',
'          WHEN ''ANULADA''   THEN ''background-color: #fce8e6; color: #c5221f;''',
'          ELSE ''background-color: #f1f3f4; color: #5f6368;''',
'       END AS estado_css,',
'       f.creado_por,',
'       f.estado,',
'       f.uuid_fiscal',
'  FROM facturas f',
'  JOIN clientes c ',
'    ON f.id_cliente = c.id_cliente ',
'   AND f.id_empresa = c.id_empresa',
' WHERE f.estado NOT IN (''CANCELADA'', ''ANULADA'', ''TIMBRADA'')',
' ORDER BY f.id_factura DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
