    'BEGIN',
    '    SELECT NVL(dias_credito, 0)',
    '      INTO v_dias',
    '      FROM condicion_pago',
    '     WHERE id_condicion_pago = :P9_CONDICION_PAGO;',
    '',
    unistr('    -- Si tiene d\00EDas de cr\00E9dito mayor a 0 (ej. Cr\00E9dito 7 D\00EDas), asignamos "POR_DEFINIR"'),
    '    IF v_dias > 0 THEN',
    '        SELECT id_forma_pago',
    '          INTO :P9_FORMA_PAGO',
    '          FROM forma_pago',
    '         WHERE codigo = ''POR_DEFINIR''',
    '           AND ROWNUM = 1;',
    '    ELSE',
    unistr('        -- Si es de contado (0 d\00EDas), limpiamos la forma de pago para obligar al usuario a elegir una inmediata'),
    '        :P9_FORMA_PAGO := NULL;',
    '    END IF;',
    'EXCEPTION',
    '    WHEN NO_DATA_FOUND THEN',
    '        NULL;',
    'END;')),
