  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '   v_id_presupuesto NUMBER;',
    'BEGIN',
    '   v_id_presupuesto := TO_NUMBER(REGEXP_SUBSTR(:P9_ID_PRESUPUESTO, ''^[0-9]+'') DEFAULT NULL ON CONVERSION ERROR);',
    '',
    '   IF v_id_presupuesto IS NOT NULL THEN',
    '      SELECT c.rif',
    '        INTO :P9_RFC_RECEPTOR',
    '        FROM presupuestos p',
    '        JOIN clientes c ON p.id_cliente = c.id_cliente',
    '       WHERE p.id_presupuesto = v_id_presupuesto;',
    '   ELSE',
    '      :P9_RFC_RECEPTOR := NULL;',
    '   END IF;',
