wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(18173084107230536)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert/update Facturacion'
,p_static_id=>'guardar-presupuesto'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_usuario       VARCHAR2(100) := v(''APP_USER'');',
'    v_fecha_emision DATE;',
'    v_tipo_cambio   NUMBER;',
'    v_total_lineas  PLS_INTEGER := 0;',
'    v_subtotal      NUMBER := NVL(fn_clean_num(:P9_SUBTOTAL), 0);',
'    v_impuesto      NUMBER := NVL(fn_clean_num(:P9_MONTO_IMPUESTO), 0);',
'    v_total         NUMBER := NVL(fn_clean_num(:P9_MONTO_TOTAL), 0);',
'BEGIN',
'    IF :P9_ID_EMPRESA IS NULL OR :P9_ID_CLIENTE IS NULL THEN',
'        raise_application_error(-20010, ''Seleccione la empresa y el cliente de la factura.'');',
'    END IF;',
'',
'    IF :P9_COD_MONEDA IS NULL OR :P9_FECHA_EMISION IS NULL THEN',
unistr('        raise_application_error(-20011, ''La moneda y la fecha de emisi\00F3n son obligatorias.'');'),
'    END IF;',
'',
'    v_fecha_emision := TO_DATE(:P9_FECHA_EMISION, ''DD/MM/YYYY'');',
'    IF UPPER(TRIM(:P9_COD_MONEDA)) IN (''VES'', ''BS'') THEN',
'        v_tipo_cambio := 1;',
'    ELSE',
'        SELECT MAX(tasa_cambio) KEEP (DENSE_RANK LAST ORDER BY fecha_vigencia)',
'          INTO v_tipo_cambio',
'          FROM tipo_cambio',
'         WHERE moneda_origen = UPPER(TRIM(:P9_COD_MONEDA))',
'           AND moneda_destino = ''VES''',
'           AND tipo_tasa = ''REAL''',
'           AND fecha_vigencia < TRUNC(v_fecha_emision) + 1;',
'',
'        IF v_tipo_cambio IS NULL OR v_tipo_cambio <= 0 THEN',
unistr('            raise_application_error(-20012, ''No existe una tasa de cambio v\00E1lida para la moneda y fecha seleccionadas.'');'),
'        END IF;',
'    END IF;',
'',
'    IF :P9_ID_FACTURA IS NOT NULL THEN',
'        SELECT COUNT(*),',
'               NVL(SUM(subtotal_linea), 0),',
'               NVL(SUM(monto_impuesto), 0),',
'               NVL(SUM(monto_total_linea), 0)',
'          INTO v_total_lineas, v_subtotal, v_impuesto, v_total',
'          FROM facturas_det',
'         WHERE id_factura = fn_clean_num(:P9_ID_FACTURA);',
'',
'        IF v_total_lineas > 0 THEN',
'            UPDATE facturas_det',
'               SET tasa_cambio_aplicada = v_tipo_cambio,',
'                   subtotal_bs = ROUND(subtotal_linea * v_tipo_cambio, 2),',
'                   total_bs = ROUND(monto_total_linea * v_tipo_cambio, 2)',
'             WHERE id_factura = fn_clean_num(:P9_ID_FACTURA);',
'',
'            :P9_SUBTOTAL := v_subtotal;',
'            :P9_MONTO_IMPUESTO := v_impuesto;',
'            :P9_MONTO_TOTAL := v_total;',
'        END IF;',
'    END IF;',
'',
'    IF ABS(v_total - (v_subtotal + v_impuesto)) > 0.01 THEN',
unistr('        raise_application_error(-20013, ''El total debe ser igual al subtotal m\00E1s los impuestos.'');'),
'    END IF;',
'',
'    :P9_TIPO_CAMBIO := v_tipo_cambio;',
'',
'    pkg_facturacion.prc_guardar_factura (',
'        p_id_factura        => :P9_ID_FACTURA,',
'        p_id_empresa        => fn_clean_num(:P9_ID_EMPRESA),',
'        p_folio_factura     => :P9_FOLIO_FACTURA,',
'        p_id_cliente        => fn_clean_num(:P9_ID_CLIENTE),',
'        p_id_presupuesto    => fn_clean_num(:P9_ID_PRESUPUESTO),',
'        p_rfc_emisor        => :P9_RFC_EMISOR,',
'        p_rfc_receptor      => :P9_RFC_RECEPTOR,',
'        p_uuid_fiscal       => :P9_UUID_FISCAL,',
'        p_uso_cfdi          => :P9_USO_CFDI,',
'        p_forma_pago        => :P9_FORMA_PAGO,',
'        p_metodo_pago       => :P9_METODO_PAGO,',
'        p_condicion_pago    => :P9_CONDICION_PAGO,',
'        p_fecha_emision     => :P9_FECHA_EMISION,',
'        p_fecha_vencimiento => :P9_FECHA_VENCIMIENTO,',
'        p_estado            => :P9_ESTADO,',
'        p_subtotal          => fn_clean_num(:P9_SUBTOTAL),',
'        p_monto_impuesto    => fn_clean_num(:P9_MONTO_IMPUESTO),',
'        p_monto_total       => fn_clean_num(:P9_MONTO_TOTAL),',
'        p_observaciones     => :P9_OBSERVACIONES,',
'        p_cod_moneda        => :P9_COD_MONEDA,',
'        p_tipo_cambio       => v_tipo_cambio,',
'        p_usuario           => v_usuario',
'    );',
'',
'    apex_application.g_print_success_message := ''Factura Guardada Exitosamente.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error al guardar la factura: #SQLERRM#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(18162756611230481)
,p_internal_uid=>18173084107230536
,p_created_on=>wwv_flow_imp.dz('20261006011538Z')
,p_updated_on=>wwv_flow_imp.dz('20261026235226Z')
,p_created_by=>'ADMIN_SYPEX'
,p_updated_by=>'ADMIN_SYPEX'
);
