wwv_flow_imp_page.create_page(
 p_id=>10
,p_name=>unistr('Detalle de Facturaci\00F3n')
,p_alias=>unistr('DETALLE-DE-FACTURACI\00D3N')
,p_page_mode=>'MODAL'
,p_step_title=>unistr('Detalle de Facturaci\00F3n')
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function calcularTotalesLinea() {',
'    var limpiarNumero = function(val) {',
'        if (!val) return 0;',
'        return parseFloat(String(val).replace(/,/g, '''')) || 0;',
'    };',
'',
'    var cantidad = limpiarNumero($v(''P10_CANTIDAD''));',
'    var precioUnitario = limpiarNumero($v(''P10_PRECIO_UNITARIO''));',
'    var pctDescuento = limpiarNumero($v(''P10_PORCENTAJE_DESCUENTO''));',
'    var montoDescuentoInput = limpiarNumero($v(''P10_MONTO_DESCUENTO''));',
'    var pctImpuesto = limpiarNumero($v(''P10_PORCENTAJE_IMPUESTO''));',
'    ',
'    // Obtener la tasa de cambio de la cabecera (o un valor predeterminado 1 si es USD)',
unistr('    // Asumiendo que en la cabecera o en la p\00E1gina existe un campo de tipo de cambio'),
'    var tipoCambio = limpiarNumero($v(''P10_TIPO_CAMBIO'') || $v(''P10_TASA_CAMBIO_APLICADA'') || $v(''P8_TIPO_CAMBIO'')) || 1;',
'',
'    var subtotal = cantidad * precioUnitario;',
'    var montoDescuento = 0;',
'',
'    if (montoDescuentoInput > 0 && pctDescuento === 0) {',
'        if (subtotal > 0) {',
'            pctDescuento = (montoDescuentoInput / subtotal) * 100;',
'        }',
'        montoDescuento = montoDescuentoInput;',
'    } else if (pctDescuento > 0) {',
'        montoDescuento = subtotal * (pctDescuento / 100);',
'    }',
'',
'    var subtotalDesc = subtotal - montoDescuento;',
'    var montoImpuesto = subtotalDesc * (pctImpuesto / 100);',
'    var totalLinea = subtotalDesc + montoImpuesto;',
'',
unistr('    // C\00E1lculos en Bol\00EDvares (VES)'),
'    var subtotalBs = subtotalDesc * tipoCambio;',
'    var totalBs = totalLinea * tipoCambio;',
'',
'    var setVal = function(id, val) {',
'        var el = document.getElementById(id);',
'        if (el) {',
'            el.value = val;',
'            jQuery(el).trigger(''validate'');',
'        }',
'    };',
'',
'    setVal(''P10_SUBTOTAL_LINEA'', subtotalDesc.toFixed(2));',
'    setVal(''P10_MONTO_DESCUENTO'', montoDescuento.toFixed(2));',
'    setVal(''P10_MONTO_IMPUESTO'', montoImpuesto.getText ? montoImpuesto.toFixed(2) : montoImpuesto.toFixed(2));',
'    setVal(''P10_MONTO_TOTAL_LINEA'', totalLinea.toFixed(2));',
'    ',
unistr('    // Asignar valores en Bol\00EDvares a los elementos de pantalla'),
'    setVal(''P10_SUBTOTAL_BS'', subtotalBs.toFixed(2));',
'    setVal(''P10_TOTAL_BS'', totalBs.toFixed(2));',
'    setVal(''P10_TASA_CAMBIO_APLICADA'', tipoCambio.toFixed(4));',
'}'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('/* Cabecera uniforme en azul degradado sin sombras/recuadros extra\00F1os */'),
'.t-DialogRegion-header,',
