,p_process_name=>'Initialize form editar detalle'
,p_static_id=>'initialize-form-editar-detalle'
,p_process_when=>'P10_ID_DETALLE'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>21946184956104084
,p_created_on=>wwv_flow_imp.dz('20261021155433Z')
