,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    ''Total Facturado (USD)'' AS titulo,',
'    ''$'' || TO_CHAR(SUM(monto_total), ''FM999,999,990.00'') AS valor,',
'    ''fa-file-text-o'' AS icono',
'FROM facturas',
'WHERE cod_moneda = ''USD''',
'UNION ALL',
'SELECT ',
'    ''Total Facturado (Bs)'',',
'    ''Bs. '' || TO_CHAR(SUM(monto_total * tipo_cambio), ''FM999,999,990.00''),',
'    ''fa-money''',
'FROM facturas',
'WHERE cod_moneda = ''VES''',
'UNION ALL',
'SELECT ',
'    ''Pendientes (USD)'',',
'    ''$'' || TO_CHAR(SUM(CASE WHEN estado = ''PENDIENTE'' THEN monto_total ELSE 0 END), ''FM999,999,990.00''),',
'    ''fa-clock-o''',
'FROM facturas',
'WHERE cod_moneda = ''USD''',
'UNION ALL',
'SELECT ',
'    ''Pendientes (Bs)'',',
'    ''Bs. '' || TO_CHAR(SUM(CASE WHEN estado = ''PENDIENTE'' THEN monto_total * tipo_cambio ELSE 0 END), ''FM999,999,990.00''),',
'    ''fa-exclamation-circle''',
'FROM facturas',
'WHERE cod_moneda = ''VES'''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
